INSERT INTO feature VALUES('package-toolchain','modules','A package''s toolchain constraints','packages','implemented','ordinary',NULL,'A package''s model states what it asks of the toolchain through `std.build`''s `Toolchain`: `gandr`, the least language version as `>= 0.3` or `>= 0.3.1`, `features`, keys of gandr''s features ledger, and `systems`, each `<architecture>-<os>` as `x86_64-linux`, an empty one asking nothing. `gandr check` holds each against the running toolchain, its version, the features ledger the binary was built with, implemented whole or in part, and the host''s system, and refuses one it leaves unmet as `ToolchainUnmet.gandr`, `ToolchainUnmet.feature.<key>` or `ToolchainUnmet.system`, naming the field and both sides, writing no manifest; a `gandr` it cannot read refuses the manifest. A met model is the manifest''s `[toolchain]` table, and a constraint is content, so an edit to it moves the address. `features` and `systems` are each one `,`-separated string until an operation''s port can be a list (#2993).','surface-dispatcher surface-driver','corpus/ledger/features/package-toolchain.gandr corpus/model/projects/workspace.gandr corpus/model/projects/tools/package.gandr crates/surface-dispatcher/src/package/toolchain.rs::package::toolchain::tests::each_unmet_constraint_is_refused_by_its_clause_3135 crates/surface-dispatcher/tests/package.rs::a_manifest_renders_the_toolchain_its_model_asks_for_3135 crates/surface-dispatcher/tests/package.rs::an_inert_edit_leaves_the_address_and_a_content_edit_moves_it_3030 crates/surface-driver/tests/cli.rs::a_package_s_toolchain_is_met_or_refused_by_its_clause_3135','corpus/ledger/features/package-toolchain.gandr','#2993');
